 Label Label(string text,int size,int x,int y,int w,int h){return new Label{Text=text,Font=new Font("Segoe UI",size,size>20?FontStyle.Bold:FontStyle.Regular),Location=new Point(x,y),Size=new Size(w,h),ForeColor=Color.Gainsboro};}
 void SetupButton(Button b,string text,int width){b.Text=text;b.Width=width;b.Height=34;b.FlatStyle=FlatStyle.Flat;b.FlatAppearance.BorderColor=Color.FromArgb(55,73,88);b.BackColor=Color.FromArgb(35,48,65);b.ForeColor=Color.White;b.UseVisualStyleBackColor=false;b.Cursor=Cursors.Hand;}
 void FillLibrary(int keep=-1){populating=true;try{library.Rows.Clear();destination.Items.Clear();int built=library.Rows.Add("0","Integrado","Developed by Conr4d","−5 dB","Solo lectura");library.Rows[built].Frozen=true;library.Rows[built].Cells[2].ToolTipText="Model 0 del CF Conr4d. Si conservas el CF v5, continúa el 5150 integrado anterior.";library.Rows[built].DefaultCellStyle.ForeColor=muted;if(bank==null)return;foreach(var slot in bank.OrderBy(s=>s.Index)){bool nam=slot.Used&&NamCatalog.ManagedName(slot.Name);var record=catalog.Find(slot.Name);string name=catalog.Friendly(slot);int row=library.Rows.Add(slot.Index+1,slot.Used?(nam?"NAM":"IR pantalla"):"Libre",name,record!=null?record.OutputDb.ToString("0.0")+" dB":"—",slot.Used?(nam?"Actualizable":"Protegido"):"Disponible");library.Rows[row].Tag=slot;library.Rows[row].Cells[2].ToolTipText=name;library.Rows[row].DefaultCellStyle.ForeColor=nam?accent:slot.Used?Color.Silver:muted;if(!slot.Used||nam)destination.Items.Add(new NamDestination{Slot=slot,Text="Model "+(slot.Index+1)+" / IR "+(slot.Index+1)+" — "+(slot.Used?"NAM: "+name:"LIBRE")});}int selected=-1;for(int n=0;n<destination.Items.Count;n++){var slot=((NamDestination)destination.Items[n]).Slot;if(slot.Index==keep){selected=n;break;}if(selected<0&&!slot.Used)selected=n;}destination.SelectedIndex=selected;replace.Checked=false;}finally{populating=false;}SyncGrid();UpdateUi();}
 void SyncGrid(){var selected=destination.SelectedItem as NamDestination;if(selected==null)return;populating=true;try{library.ClearSelection();foreach(DataGridViewRow row in library.Rows){var slot=row.Tag as PodIrSlot;if(slot!=null&&slot.Index==selected.Slot.Index){row.Selected=true;library.FirstDisplayedScrollingRowIndex=Math.Max(1,row.Index-4);break;}}}finally{populating=false;}}
 void SetupLevel(NumericUpDown level,decimal value){level.Minimum=-60;level.Maximum=12;level.DecimalPlaces=1;level.Increment=.5M;level.Value=value;level.Width=85;level.BackColor=Color.FromArgb(35,48,65);level.ForeColor=Color.Gainsboro;}
 NamCapture BuildCapture(string file,double volume,bool auto){var raw=NamCapture.Read(file);double db=auto?NamLoudness.OutputFor(NamCapture.AudioPayload(raw.Wave)):volume;return NamCapture.Read(file,db);}
 void ApplyCapture(NamCapture prepared,bool restore){capture=prepared;changingLevel=true;try{sendLevel.Value=(decimal)capture.OutputDb;}finally{changingLevel=false;}if(restore)shortName.Text=NamTitle.Suggest(capture.Name);savedLevels[capture.Hash]=capture.OutputDb;if(!preview){Directory.CreateDirectory(Path.GetDirectoryName(levelsPath));File.WriteAllText(levelsPath,new JavaScriptSerializer().Serialize(savedLevels));}captureInfo.Text=capture.Name+"\nA2 Lite · 48 kHz";autoInfo.Text=automatic.Checked?"Referencia: Developed by Conr4d · −5 dB":"Volumen manual";status.Text="";Log("NAM preparado: "+capture.Name+" · "+UiText.T("Volumen")+" "+capture.OutputDb.ToString("0.0")+" dB");UpdateUi();}
 void RestoreVolume(string file){double value;var source=NamCapture.Read(file);changingLevel=true;try{sendLevel.Value=(decimal)(savedLevels.TryGetValue(source.Hash,out value)?value:-5);}finally{changingLevel=false;}}
 void LoadCapture(string file,bool restore=true,bool forceDefault=false){try{if(restore)RestoreVolume(file);ApplyCapture(BuildCapture(file,(double)sendLevel.Value,automatic.Checked),restore);}catch(Exception e){capture=null;captureInfo.Text="Archivo rechazado";status.ForeColor=Color.Salmon;status.Text=e.Message;Log(e.Message);}UpdateUi();}
 async Task PrepareFile(string file,bool restore){prepareTimer.Stop();preparationPending=false;await Work(async()=>{status.ForeColor=accent;status.Text=automatic.Checked?"Analizando NAM con la referencia a −5 dB…":"Preparando NAM…";if(restore)RestoreVolume(file);double volume=(double)sendLevel.Value;bool auto=automatic.Checked;try{var prepared=await Task.Run(()=>BuildCapture(file,volume,auto));ApplyCapture(prepared,restore);}catch{capture=null;captureInfo.Text="Archivo rechazado";throw;}});}
 void SchedulePreparation(){if(changingLevel||busy||capture==null)return;prepareTimer.Stop();prepareTimer.Start();preparationPending=true;UpdateUi();}
 PodIrSlot SelectedNam(){if(library.SelectedRows.Count!=1)return null;var slot=library.SelectedRows[0].Tag as PodIrSlot;return slot!=null&&slot.Used&&NamCatalog.ManagedName(slot.Name)?slot:null;}
 async Task DeleteSelectedNam(){if(preview||IsBusy||!IsOnline)return;var chosen=SelectedNam();if(chosen==null)return;string text="Model "+(chosen.Index+1)+" · "+catalog.Friendly(chosen)+"\n\n"+UiText.T("Se guardará una copia previa y se liberará esta posición. Los presets que la usan dejarán de encontrar este NAM.");if(MessageBox.Show(this,text,UiText.T("Borrar NAM"),MessageBoxButtons.OKCancel,MessageBoxIcon.Warning,MessageBoxDefaultButton.Button2)!=DialogResult.OK)return;await Work(async()=>{string result=await session.Delete(chosen.Index,chosen);bank=session.State.Bank;FillLibrary(chosen.Index);status.ForeColor=accent;status.Text=result;});}
 async Task EditSelectedVolume(){if(preview||IsBusy||!IsOnline)return;var chosen=SelectedNam();if(chosen==null)return;var record=catalog.Find(chosen.Name);if(record==null){status.ForeColor=Color.Salmon;status.Text="Este PC no conserva los niveles de este NAM. Abre su archivo original para actualizarlo.";return;}await Work(async()=>{var payload=await session.ReadManaged(chosen.Index,chosen);using(var dialog=new NamVolumeDialog(chosen.Index+1,catalog.Friendly(chosen),record,payload)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;string result=await session.ChangeVolume(chosen.Index,chosen,dialog.VolumeDb);bank=session.State.Bank;catalog=session.Catalog;FillLibrary(chosen.Index);status.ForeColor=accent;status.Text=result;}});}
 void UpdateUi(bool rebuildSummary=true){bool online=session!=null&&session.Connected;var chosen=destination.SelectedItem as NamDestination;bool replacing=chosen!=null&&chosen.Slot.Used;connect.Enabled=!preview&&!IsBusy&&!online;refresh.Enabled=!IsBusy&&online;disconnect.Enabled=!IsBusy&&online;choose.Enabled=!IsBusy;shortName.Enabled=!busy&&capture!=null;sendLevel.Enabled=!busy&&!automatic.Checked;automatic.Enabled=!busy;var selected=SelectedNam();deleteNam.Enabled=!preview&&!IsBusy&&online&&selected!=null;editLevels.Enabled=deleteNam.Enabled&&catalog.Find(selected.Name)!=null;captureOk.Visible=capture!=null;destination.Enabled=!busy&&bank!=null;library.Enabled=!busy;replace.Enabled=!busy&&replacing;replace.Visible=replacing;replaceHint.Visible=!replacing;help.Text=replacing?"Afecta a los presets que usan Model "+(chosen.Slot.Index+1)+". Para recargarlo, selecciona otro Model y vuelve a éste.":"El nivel se aplica al enviar. Después selecciona el Model indicado en la POD Go.";replaceHint.Text=chosen==null?"Elige una posición de destino.":"Destino libre: no se sustituirá ningún contenido.";send.Enabled=!preview&&!busy&&!preparationPending&&online&&capture!=null&&NamTitle.Valid(shortName.Text)&&chosen!=null;send.Text=chosen==null?"Elige un destino":(replacing?"Sustituir Model ":"Cargar en Model ")+(chosen.Slot.Index+1);((StudioButton)send).Glow=send.Enabled;send.Invalidate();send.BackColor=send.Enabled?accent:Color.FromArgb(35,48,65);send.ForeColor=send.Enabled?bg:muted;if(rebuildSummary){if(chosen==null)summary.Text="Conecta y elige una posición disponible.";else summary.Text=(capture==null?"Elige un NAM":capture.Name)+"\n"+NamTitle.Preview(chosen.Slot.Index+1,shortName.Text)+"\n→ Model "+(chosen.Slot.Index+1)+" / IR "+(chosen.Slot.Index+1)+" · "+sendLevel.Value.ToString("0.0")+" dB\n"+(replacing?"Sustituirá un NAM; se conservará una copia previa.":"Espacio libre; tus IR de pantalla se conservan.");}if(ViewStateChanged!=null)ViewStateChanged();}
 protected override void Dispose(bool disposing){if(disposing)prepareTimer.Dispose();base.Dispose(disposing);}
 async Task Work(Func<Task> action){busy=true;UpdateUi();try{await action();}catch(Exception e){status.Text=e.Message;status.ForeColor=Color.Salmon;Log("ERROR: "+e.Message);}finally{busy=false;if(session!=null&&!session.Connected)connection.Text="Sin conectar";UpdateUi();}}
 void Log(string message){string line=DateTime.Now.ToString("HH:mm:ss.fff")+" "+message;if(!preview)File.AppendAllText(Path.Combine(records,"session.log"),line+Environment.NewLine);if(IsHandleCreated&&InvokeRequired)BeginInvoke(new Action<string>(LogUi),line);else LogUi(line);}
 void LogUi(string line){if(!IsDisposed)journal.AppendText(line+Environment.NewLine);}
 public void SelectPreviewModel(int model){library.ClearSelection();foreach(DataGridViewRow row in library.Rows){var slot=row.Tag as PodIrSlot;if((slot==null?0:slot.Index+1)==model){row.Selected=true;library.CurrentCell=row.Cells[0];break;}}}
 public void Render(string path,int model=-1){ShowInTaskbar=false;StartPosition=FormStartPosition.Manual;Location=new Point(-25000,-25000);Show();Application.DoEvents();SyncGrid();if(model>=0){library.ClearSelection();foreach(DataGridViewRow row in library.Rows){var slot=row.Tag as PodIrSlot;if((slot==null?0:slot.Index+1)==model){row.Selected=true;library.CurrentCell=row.Cells[0];break;}}}Application.DoEvents();using(var bitmap=new Bitmap(Width,Height)){DrawToBitmap(bitmap,new Rectangle(Point.Empty,Size));bitmap.Save(path);}Hide();}
}
